package org.infinilect.app.reader.epub

import org.infinilect.app.ui.LocalizedStrings
import org.infinilect.app.ui.UiText

/** UI wrappers generated by the parser, never publisher text or image alt metadata. */
private fun localizedImageRun(run: EpubRun, strings: LocalizedStrings): EpubRun {
    if (run.translatable) return run
    val text = run.text
    val label = when {
        text == "[Image not rendered]" -> strings[UiText.IMAGE_NOT_RENDERED]
        text.startsWith("[Image: ") && text.endsWith("]") -> strings.format(UiText.IMAGE_ALT_FALLBACK, text.substring(8, text.length - 1))
        else -> return run
    }
    return if (label == text) run else run.copy(text = label)
}

/** Bounded presentation-only projection; reuse the existing original-offset mapping.
 * Returning the original projection when nothing changes avoids work in ordinary books.
 * In mixed paragraphs, offsets after an image alternative still address original text. */
internal fun localizedEpubImages(blocks: List<EpubBlock>, translated: List<EpubTranslatedBlock>?, strings: LocalizedStrings): List<EpubTranslatedBlock>? {
    var changed: MutableMap<Int, EpubTranslatedBlock>? = null
    blocks.forEachIndexed { index, source ->
        val current = translated?.getOrNull(index)?.takeIf { it.source === source }
        val runs = current?.runs ?: source.runs
        var replacement: MutableList<EpubRun>? = null
        for ((i, run) in runs.withIndex()) {
            val localized = localizedImageRun(run, strings)
            if (localized !== run) {
                if (replacement == null) replacement = runs.toMutableList()
                replacement[i] = localized
            }
        }
        if (replacement != null) {
            if (changed == null) changed = mutableMapOf()
            changed[index] = EpubTranslatedBlock(source, replacement)
        }
    }
    val localized = changed ?: return translated
    return blocks.mapIndexed { index, block -> localized[index]
        ?: translated?.getOrNull(index)?.takeIf { it.source === block }
        ?: EpubTranslatedBlock(block, block.runs) }
}
